const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const row = db.prepare('SELECT * FROM flight_bookings WHERE booking_id = ?').get('C4C633');
if (row) {
  // Parse JSON fields for readability
  const parsed = {...row};
  parsed.flights = JSON.parse(row.flights_json || '[]');
  parsed.passengers = JSON.parse(row.passengers_json || '[]');
  parsed.payment_history = JSON.parse(row.payment_history_json || '[]');
  delete parsed.flights_json;
  delete parsed.passengers_json;
  delete parsed.payment_history_json;
  console.log(JSON.stringify(parsed, null, 2));
} else {
  console.log('Reservation C4C633 not found');
}
db.close();
"

